// Idempotency & De-duplication Cache Check
// In production, backed by Redis or Bubble Notification Log query
const authorId = $json.body?.author_id || $json.author_id;
const idempotencyKey = $json.body?.idempotency_key || $json.idempotency_key || `${authorId}-${new Date().toISOString().slice(0, 10)}`;

const staticData = $getWorkflowStaticData('global');
staticData.processedKeys = staticData.processedKeys || {};

const now = Date.now();
const lastProcessedTime = staticData.processedKeys[idempotencyKey];

// De-duplicate within a 3-minute sliding window
const isDuplicate = lastProcessedTime && (now - lastProcessedTime < 180000);

if (!isDuplicate) {
  staticData.processedKeys[idempotencyKey] = now;
}

return {
  ...$json,
  isDuplicate,
  idempotencyKey,
  authorId
};

// Knowledge Base Grounding & Financial Metrics Aggregator
const body = $json.body || $json;
const author = body.author || body;
const books = author.books || [];

let totalSold = 0;
let totalEarned = 0;
let totalPaid = 0;
let totalPending = 0;
let hasOverdue = false;

const now = new Date();
const publishedBooks = [];
const inProductionBooks = [];

for (const b of books) {
  if (b.status === 'Published & Live') {
    totalSold += Number(b.total_copies_sold || 0);
    totalEarned += Number(b.total_royalty_earned || 0);
    totalPaid += Number(b.royalty_paid || 0);
    totalPending += Number(b.royalty_pending || 0);

    let isOverdue = false;
    if (Number(b.royalty_pending || 0) > 0) {
      if (b.last_royalty_payout_date) {
        const daysSinceLast = (now - new Date(b.last_royalty_payout_date)) / (1000 * 3600 * 24);
        if (daysSinceLast > 90) isOverdue = true;
      } else if (b.publication_date) {
        const daysSincePub = (now - new Date(b.publication_date)) / (1000 * 3600 * 24);
        if (daysSincePub > 90) isOverdue = true;
      }
    }
    if (isOverdue) hasOverdue = true;

    publishedBooks.push({
      title: b.title,
      isbn: b.isbn || 'Assigned',
      genre: b.genre,
      copies_sold: b.total_copies_sold,
      royalty_earned: b.total_royalty_earned,
      royalty_paid: b.royalty_paid,
      royalty_pending: b.royalty_pending,
      status_badge: (b.royalty_pending === 0) ? 'Green' : (isOverdue ? 'Red' : 'Yellow'),
      last_payout: b.last_royalty_payout_date || 'No Payout Yet'
    });
  } else {
    inProductionBooks.push({
      title: b.title,
      stage: b.status.replace('In Production - ', '') || 'Production Pipeline'
    });
  }
}

// Quarterly Payout Calculation (45 days post quarter end)
const month = now.getMonth(); // 0-11
let upcomingQuarter = 'Q1';
let upcomingPayoutDate = 'May 15';
if (month >= 3 && month <= 5) {
  upcomingQuarter = 'Q2';
  upcomingPayoutDate = 'August 15';
} else if (month >= 6 && month <= 8) {
  upcomingQuarter = 'Q3';
  upcomingPayoutDate = 'November 15';
} else if (month >= 9 && month <= 11) {
  upcomingQuarter = 'Q4';
  upcomingPayoutDate = 'February 15';
}

const thresholdMet = totalPending >= 1000;

return {
  author_id: author.author_id,
  name: author.name,
  email: author.email,
  city: author.city,
  total_books: books.length,
  total_copies_sold: totalSold,
  total_royalty_earned: totalEarned,
  total_royalty_paid: totalPaid,
  total_royalty_pending: totalPending,
  has_overdue: hasOverdue,
  threshold_met: thresholdMet,
  upcoming_quarter: upcomingQuarter,
  upcoming_payout_date: upcomingPayoutDate,
  published_books: publishedBooks,
  in_production_books: inProductionBooks,
  trigger_type: body.trigger_type || 'Manual Single',
  idempotency_key: $json.idempotencyKey
};

