// Email Formatter & Resilient Fallback Engine
const prev = $('Aggregate Metrics & Knowledge Base Policy Engine').first().json;
const aiResponse = $json;

let emailBody = '';
let isAiGenerated = false;

if (aiResponse?.choices?.[0]?.message?.content) {
  emailBody = aiResponse.choices[0].message.content.trim();
  isAiGenerated = true;
} else {
  // Deterministic Knowledge-Grounded Fallback Template
  const bookBreakdown = prev.published_books.map(b => 
    `• "${b.title}" (ISBN: ${b.isbn}) | Genre: ${b.genre} | Sold: ${b.copies_sold} copies | Earned: ₹${b.royalty_earned.toLocaleString('en-IN')} | Paid: ₹${b.royalty_paid.toLocaleString('en-IN')} | Pending: ₹${b.royalty_pending.toLocaleString('en-IN')}`
  ).join('\n');

  let productionNote = '';
  if (prev.in_production_books && prev.in_production_books.length > 0) {
    productionNote = '\n\n⏳ Books Currently in Production:\n' + 
      prev.in_production_books.map(p => `• "${p.title}": Currently in ${p.stage}. Our production team is actively polishing your manuscript for release.`).join('\n');
  }

  let payoutMessage = '';
  if (prev.total_royalty_pending === 0) {
    payoutMessage = '🎉 Congratulations! All accrued royalties for your titles are fully settled and paid up to date.';
  } else if (prev.total_royalty_pending < 1000) {
    payoutMessage = `💡 Note on Balance: Your pending balance is ₹${prev.total_royalty_pending.toLocaleString('en-IN')}. Per BookLeaf policy, royalties are disbursed once the ₹1,000 minimum threshold is reached. Your current balance will safely roll over to the next quarter.`;
  } else {
    payoutMessage = `📅 Payout Schedule: Your pending balance of ₹${prev.total_royalty_pending.toLocaleString('en-IN')} is scheduled for direct bank disbursement by ${prev.upcoming_payout_date} (within our quarterly 45-day window).`;
  }

  emailBody = `Subject: BookLeaf Publishing Royalty Summary — ${prev.name}

Dear ${prev.name},

We are delighted to share your latest publishing statement and royalty summary with BookLeaf Publishing.

📊 Performance Summary Overview:
• Total Published Books: ${prev.total_books}
• Lifetime Copies Distributed: ${prev.total_copies_sold}
• Total Royalty Accrued: ₹${prev.total_royalty_earned.toLocaleString('en-IN')}
• Total Royalty Paid: ₹${prev.total_royalty_paid.toLocaleString('en-IN')}
• Outstanding Pending Royalty: ₹${prev.total_royalty_pending.toLocaleString('en-IN')}

📚 Detailed Book Performance:
${bookBreakdown}${productionNote}

${payoutMessage}

Thank you for sharing your voice with readers worldwide through BookLeaf Publishing. If you have any questions regarding your statement, feel free to reply directly or contact your Author Support Representative.

Warm regards,
Author Relations & Royalties Desk
BookLeaf Publishing
support@bookleafpublishing.com`;
}

return {
  author_id: prev.author_id,
  author_name: prev.name,
  author_email: prev.email,
  trigger_type: prev.trigger_type,
  status: 'Success',
  email_content: emailBody,
  is_ai_generated: isAiGenerated,
  sent_timestamp: new Date().toISOString(),
  idempotency_key: prev.idempotency_key
};
